/** 
 * Request for quick stop then blocks until process is stopped. Returns immediately if the process is disabled in configuration.
 */
private void hardStopProcess(ProcessId processId){
  ManagedProcessHandler process=processesById.get(processId);
  if (process != null) {
    try {
      process.hardStop();
    } catch (SecurityException e) {
      // Handle permission issues, e.g., log or rethrow as a custom exception
      System.err.println("SecurityException occurred: " + e.getMessage());
    } catch (InterruptedException e) {
      // Restore the interrupted status and handle the interruption
      Thread.currentThread().interrupt();
      System.err.println("InterruptedException occurred: " + e.getMessage());
    }
  }
}
